#include <WiFi.h>

#define BTN_PIN    0    // кнопка BOOT на плате — можно не паять ничего
#define LED_PIN    48   // onboard RGB светодиод на большинстве ESP32-S3

const char* NAMES[] = {
  "7A Klassu Salam",
  "Geografichke Salam",
  "Russichke Salam",
  "Nina Igorevna Salam"
};
// цвета: красный, жёлтый, зелёный, синий (R, G, B)
const uint8_t COLORS[][3] = {
  {255, 0,   0},
  {255, 255, 0},
  {0,   255, 0},
  {0,   0,   255}
};
const int COUNT = sizeof(NAMES) / sizeof(NAMES[0]);

int current = 0;

void applyIndex(int idx) {
  current = idx % COUNT;

  WiFi.softAPdisconnect(true);
  delay(30);
  WiFi.softAP(NAMES[current], "", 6);

  // цвет светодиода
  neopixelWrite(LED_PIN,
                COLORS[current][0],
                COLORS[current][1],
                COLORS[current][2]);

  Serial.printf("Сеть: %s\n", NAMES[current]);
}

void setup() {
  Serial.begin(115200);
  delay(1000);

  pinMode(BTN_PIN, INPUT_PULLUP);
  neopixelWrite(LED_PIN, 0, 0, 0);  // погасить LED до старта

  WiFi.mode(WIFI_AP);
  WiFi.setTxPower(WIFI_POWER_8_5dBm);  // меньше пиковый ток — нет brownout

  applyIndex(0);
}

void loop() {
  // кнопка нажимается на GND (у BOOT-кнопки резисторы уже есть)
  if (digitalRead(BTN_PIN) == LOW) {
    delay(40);                              // антидребезг
    if (digitalRead(BTN_PIN) == LOW) {
      applyIndex(current + 1);
      while (digitalRead(BTN_PIN) == LOW) delay(10);  // ждём отпускания
    }
  }
}
